from pathlib import Path
import json,html
R=Path(__file__).resolve().parent;s=json.loads((R/'data/story.json').read_text());esc=html.escape
css='''@font-face{font-family:Barlow;src:url(brand/barlow-400.woff2);font-weight:400}@font-face{font-family:Barlow;src:url(brand/barlow-600.woff2);font-weight:600}@font-face{font-family:Bitcount;src:url(brand/bitcount-latin.woff2);font-weight:100 900}*{box-sizing:border-box}html,body{margin:0;background:#111;color:#f5f5f7;font-family:Barlow,Arial,sans-serif}.page{width:1280px;height:720px;padding:52px 70px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 80% 10%,#3e3e4244,transparent 50%),#1c1c1e;page-break-after:always}.logo{font-family:Bitcount,sans-serif;font-weight:200;letter-spacing:.04em;-webkit-text-stroke:.012em;text-shadow:.033em 0, -.033em 0,0 .033em,0 -.033em;font-size:36px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ffffff1a;padding-bottom:20px;color:#ebebf5b8}.top span:last-child{font-size:16px;letter-spacing:.1em}h1{font-size:66px;font-weight:600;line-height:1.03;letter-spacing:-.025em;margin:52px 0 20px}h2{font-size:40px;font-weight:600;line-height:1.1;margin:28px 0 20px}h3{font-size:26px;font-weight:600;margin:0 0 12px}p{font-size:23px;line-height:1.4;color:#ebebf5b8;margin:15px 0}.eyebrow{font-size:17px;letter-spacing:.12em;text-transform:uppercase;color:#80bfff}.cols{display:grid;grid-template-columns:1fr 1fr;gap:30px}.three{grid-template-columns:1fr 1fr 1fr}.box{padding:25px;border:1px solid #ffffff1a;border-radius:24px;background:linear-gradient(130deg,#ffffff08,#ffffff02);box-shadow:inset 0 1px 1px #fff2}.small{font-size:18px}.foot{position:absolute;bottom:26px;left:70px;right:70px;display:flex;justify-content:space-between;color:#ebebf585;font-size:15px}.board{display:grid;grid-template-columns:825px 1fr;gap:28px;margin-top:28px;align-items:start}.board img{width:825px;border-radius:10px;border:1px solid #ffffff1a}.board h2{font-size:28px;margin:0 0 16px}.board p{font-size:19px;line-height:1.4}.note{color:#9acbff}.vo p{font-size:21px;line-height:1.42}.vo .time{color:#80bfff;font-size:16px}.timeline{width:100%;border-collapse:collapse;margin-top:24px}.timeline td{padding:16px 10px;border-bottom:1px solid #ffffff16;font-size:20px;vertical-align:top}.timeline td:first-child{white-space:nowrap;color:#80bfff;width:115px}.timeline td:nth-child(2){width:285px}.timeline p{font-size:18px;margin:0}.swatches{display:flex;gap:15px;margin:30px 0}.swatch{width:155px;padding:14px;border-radius:16px;border:1px solid #ffffff1a}.swatch i{display:block;height:58px;border-radius:8px;margin-bottom:15px}.swatch span{font-size:18px}.swatch small{display:block;color:#ebebf5b8;margin-top:5px}.num{font-size:55px;color:#f5f5f7}.page.cover .quote{font-size:35px;line-height:1.4;color:#f5f5f7;max-width:950px}a{color:#9acbff;text-decoration:none}.cover h1{font-size:60px;margin:32px 0 16px}.page.cover .quote{font-size:29px;line-height:1.35}.cover .num{font-size:42px}.cover .cols p{font-size:21px}.timeline td{padding:12px 10px;font-size:18px}.timeline p{font-size:17px;line-height:1.3}.swatches{margin:20px 0}.swatch{padding:12px}.swatch i{height:45px;margin-bottom:12px}.box p{font-size:21px}.box .small{font-size:17px}@page{size:1280px 720px;margin:0}@media print{html,body{background:#1c1c1e}.page{-webkit-print-color-adjust:exact;print-color-adjust:exact;margin:0}}'''
pages=[]
def page(title,body,cls=''):
 n=len(pages)+1;pages.append(f'<section class="page {cls}"><div class="top"><span class="logo">JERP</span><span>{title}</span></div>{body}<div class="foot"><span>THE UNSUPPORTED LEAP · PREPRODUCTION v1.0 · 25.10.2026</span><span>{n:02d}</span></div></section>')
page('CREATIVE TREATMENT', '''<div class="eyebrow" style="margin-top:50px">49 seconds / 9 shots / 1 continuous example</div><h1>The Unsupported Leap</h1><p class="quote">Уверенное утверждение выходит за край своего основания.<br>JERP возвращает ответ к тому, что поддерживает источник.</p><div class="cols three" style="margin-top:35px"><div><div class="num">01</div><p>Проблема понятна<br>с первого примера</p></div><div><div class="num">02</div><p>Эффекты объясняют<br>проверку, а не украшают её</p></div><div><div class="num">03</div><p>Настоящие ассеты<br>и визуальный язык сайта</p></div></div>''','cover')
page('THE STORY', '''<h2>Страница говорит trial.<br>AI обещает forever.</h2><div class="cols"><div class="box"><div class="eyebrow">SOURCE · FICTIONAL DEMO</div><p style="color:#f5f5f7;font-size:30px">Free trial available.</p><p>A paid subscription is required<br>after the trial.</p></div><div class="box"><div class="eyebrow">AI DRAFT</div><p style="color:#f5f5f7;font-size:30px">The best choice.<br>Free forever.</p></div></div><p style="margin-top:30px">JERP помогает различить подтверждённое условие, прямое противоречие и мнение. В AI-контекст возвращается небольшой пакет фактов с источниками.</p><p class="small">Учебный пример на northstar.example. Не запись реального вызова MCP и не обещание безошибочного AI.</p>''')
notes=[
 ('08s / THE LEAP','Слова Free forever остаются над пустотой за краем документа. Тень и параллакс делают отсутствие основания видимым.','Lateral track → stop → match cut по кромке стекла.'),
 ('16s / THE CHECK','Входящий контент встречает проверку до использования в ответе. Wordmark и стекло — из системы сайта; никакого магического щита.','Стеклянная поверхность поворачивается ребром и разделяет утверждения.'),
 ('28s / THE VERDICTS','true — поддержано источником. false — источник противоречит. not_fact — мнение. Каждая метка читается словами, не только цветом.','Общий неподвижный hold 4 s. Два подтверждённых условия переходят дальше.'),
 ('34s / COMPACT CONTEXT','Полная страница остаётся снаружи. В контекст входит небольшая карточка фактов вместе с источником и в заданном размере.','Карточка становится основой ответа. Без придуманных счётчиков экономии.'),
 ('40s / THE ANSWER','Те же условия, которые были в начале, теперь читаются в ответе. Source-tab раскрывает поддерживающий фрагмент.','Источник не исчезает при сборке ответа. Решение остаётся за пользователем.'),
 ('47s / THE INVITATION','Настоящий dotted wordmark и сфера, исходный слоган, один Try Free. Последние 3 s — неподвижный CTA.','Титры в карточках — Barlow. Wordmark — Bitcount по CSS сайта.')]
for i,(title,body,note) in enumerate(notes,1):
 page(title,f'<div class="board"><img src="boards/styleframe-{i}.png" alt="Styleframe {i}"><div><h2>{esc(title.split(" / ")[1])}</h2><p>{esc(body)}</p><p class="note">{esc(note)}</p><p class="small">Композиционный кадр. Перспектива и стекло здесь — CSS-study, не финальный Blender-рендер.</p></div></div>')
for lo,hi in [(0,5),(5,9)]:
 rows=''.join(f'<tr><td>{x["start"]:02d}–{x["end"]:02d}s</td><td>{esc(x["title"])}</td><td><p>{esc(x["action_ru"].split('. ')[0]+'.')}</p></td></tr>' for x in s['shots'][lo:hi])
 page('TIMELINE / '+('I' if lo==0 else 'II'),f'<h2>Монтажная причинность</h2><table class="timeline">{rows}</table>')
vo=[]
for group in [s['shots'][:3],s['shots'][3:6],s['shots'][6:]]:
 vo.append('<div>'+''.join(f'<div class="time">{x["start"]:02d}–{x["end"]:02d}s</div><p>{esc(x["vo"])}</p>' for x in group)+'</div>')
page('THE WORDS', '<h2>Английская озвучка · 93 слова</h2><div class="cols three vo">'+''.join(vo)+'</div><p class="small" style="margin-top:35px">Спокойная подача, 135–145 слов/мин во время речи; около 8–10 s остаётся на паузы и чтение. Тайминг предварительный, голос ещё не записан.</p>')
swatches=[('Canvas','#1c1c1e'),('Surface','#2c2c2e'),('Ink','#f5f5f7'),('Primary','#0a84ff'),('Danger','#ff6b6b')]
sw=''.join(f'<div class="swatch"><i style="background:{c}"></i><span>{n}</span><small>{c}</small></div>' for n,c in swatches)
page('THE BRAND',f'''<h2>Система сайта, а не новая палитра</h2><div class="swatches">{sw}</div><div class="cols"><div class="box"><h3 class="logo" style="font-size:53px">JERP</h3><p>Bitcount 200 · tracking .04em<br>stroke .012em · original shadow</p><p class="small">Wordmark восстановлен из реальных CSS-правил сайта. favicon.svg — отдельная стеклянная эмблема.</p></div><div class="box"><h3>Barlow + glass</h3><p>Barlow 400 / 600 для читаемого текста.<br>Радиусы 24 / 32 px. Белый мягкий блик.</p><p class="small">На главной: графит, стекло, точки, сфера. Бирюзовая палитра предыдущего эскиза исключена.</p></div></div>''')
page('TONE OF VOICE', '''<h2>Спокойная уверенность,<br>которую можно проверить.</h2><div class="cols"><div class="box"><h3>Говорим</h3><p>The page says…<br>Supported by source.<br>You can check the source.<br>Less for your AI to read.</p></div><div class="box"><h3>Не обещаем</h3><p>Always right.<br>100% safe.<br>Never hallucinates.<br>Guaranteed savings.</p></div></div><p>Задача и результат — крупно. Названия инструментов — малыми лейблами. Пользователь не обязан знать MCP, чтобы понять ролик.</p>''')
page('FROM SCRIPT TO FILM', '''<h2>Сначала проверяем историю.<br>Потом считаем кадры.</h2><div class="cols three"><div class="box"><h3>Сейчас</h3><p>Сценарий, VO, 9 шотов, 6 styleframes, токены и источники.</p></div><div class="box"><h3>Следом</h3><p>Animatic со scratch VO: чтение, темп и непрерывность переходов.</p></div><div class="box"><h3>После</h3><p>Blender, композ, звук. 1080p / 30 fps / 1470 кадров.</p></div></div><p style="margin-top:30px">Проверка без звука, читаемость на 640 px, различие false / not_fact, один источник от начала до конца, CTA ≥3 s. Числа confidence и экономии не выдумываются.</p><p class="small">ASTRA использована один раз: концепция, драматургия и аудит обещаний. Исследование, ассеты, сборка и проверки выполнены основным агентом.</p>''')
(R/'review-deck.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>JERP · The Unsupported Leap · Treatment</title><style>'+css+'</style><body>'+''.join(pages)+'</body></html>')
print(len(pages),'slides generated')
